namespace Finora.Api.Data;

public enum AccountType { Cash, CurrentAccount, Savings, CreditCard, Investment, Other }
public enum CategoryType { Income, Expense }
public enum TransactionType { Income, Expense, Transfer }
public enum RecurringFrequency { Weekly, Monthly, Quarterly, Yearly }
public enum MortgageRateType { Fixed, Variable, Mixed }
public enum HouseholdBillType { Water, Electricity, Gas, Internet, MobilePlan }
public enum MedicalExpenseType { Pharmacy, Appointment, Exam, Treatment, Insurance, Other }
public enum SupermarketExpenseType { Groceries, HouseholdSupplies, PersonalCare, Baby, Pet, Other }

public sealed class Account { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Name { get; set; } = ""; public AccountType AccountType { get; set; } public string CurrencyCode { get; set; } = "EUR"; public decimal InitialBalance { get; set; } public bool IsArchived { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Category { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Name { get; set; } = ""; public CategoryType CategoryType { get; set; } public string? Icon { get; set; } public bool IsDefault { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Transaction { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public Guid AccountId { get; set; } public Guid? CategoryId { get; set; } public TransactionType TransactionType { get; set; } public decimal Amount { get; set; } public string Description { get; set; } = ""; public DateOnly TransactionDate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Budget { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public Guid CategoryId { get; set; } public decimal Amount { get; set; } public int Month { get; set; } public int Year { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class RecurringTransaction { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public Guid AccountId { get; set; } public Guid? CategoryId { get; set; } public TransactionType TransactionType { get; set; } public decimal Amount { get; set; } public string Description { get; set; } = ""; public RecurringFrequency Frequency { get; set; } public DateOnly StartDate { get; set; } public DateOnly NextOccurrenceDate { get; set; } public DateOnly? EndDate { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Mortgage { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Name { get; set; } = ""; public string Lender { get; set; } = ""; public string? PropertyAddress { get; set; } public decimal OriginalPrincipal { get; set; } public decimal OutstandingBalance { get; set; } public decimal InterestRate { get; set; } public MortgageRateType RateType { get; set; } public decimal MonthlyPayment { get; set; } public string CurrencyCode { get; set; } = "EUR"; public DateOnly StartDate { get; set; } public DateOnly EndDate { get; set; } public int PaymentDay { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class HouseholdBill { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Name { get; set; } = ""; public string Provider { get; set; } = ""; public HouseholdBillType BillType { get; set; } public decimal Amount { get; set; } public string CurrencyCode { get; set; } = "EUR"; public int BillingDay { get; set; } public DateOnly StartDate { get; set; } public DateOnly? EndDate { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class MedicalExpense { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Description { get; set; } = ""; public string Provider { get; set; } = ""; public MedicalExpenseType ExpenseType { get; set; } public decimal Amount { get; set; } public string CurrencyCode { get; set; } = "EUR"; public DateOnly ExpenseDate { get; set; } public string? Notes { get; set; } public bool IsReimbursable { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class SupermarketExpense { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public string Store { get; set; } = ""; public string Description { get; set; } = ""; public SupermarketExpenseType ExpenseType { get; set; } public decimal Amount { get; set; } public string CurrencyCode { get; set; } = "EUR"; public DateOnly ExpenseDate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
